    <script>
        document.addEventListener('DOMContentLoaded', () => {
            const form = document.getElementById('contact-form');
            const statusMessage = document.getElementById('status-message');

            const fields = {
                name: {
                    element: document.getElementById('name'),
                    errorElement: document.getElementById('name-error'),
                    validate: (value) => value.trim() !== '' ? '' : 'Error: Full name is required.'
                },
                email: {
                    element: document.getElementById('email'),
                    errorElement: document.getElementById('email-error'),
                    validate: (value) => {
                        if (!value.trim()) return 'Error: Email address is required.';
                        const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
                        return emailRegex.test(value) ? '' : 'Error: Enter a valid email address like name@example.com.';
                    }
                },
                phone: {
                    element: document.getElementById('phone'),
                    errorElement: document.getElementById('phone-error'),
                    validate: (value) => {
                        if (!value.trim()) return ''; // Optional
                        const phoneRegex = /^\d{3}-\d{3}-\d{4}$/;
                        return phoneRegex.test(value) ? '' : 'Error: Enter a valid phone number like 123-456-7890.';
