                let firstInvalidField = null;
                let isValid = true;

                Object.keys(fields).forEach(fieldId => {
                    if (!validateField(fieldId)) {
                        isValid = false;
                        if (!firstInvalidField) {
                            firstInvalidField = fields[fieldId].element;
                        }
