</head>
<body>
    <main class="container">
        <h1>Contact Support</h1>
        <p>Fields marked with <span class="required-indicator" aria-hidden="true">*</span> are required.</p>

        <form id="contact-form" novalidate>
            <div class="form-field">
                <label for="name">Full name <span class="required-indicator" aria-hidden="true">*</span></label>
                <input 
                    type="text" 
                    id="name" 
                    name="name" 
                    required 
                    autocomplete="name"
                    aria-describedby="name-error"
                    aria-invalid="false">
                <p id="name-error" class="error-message"></p>
            </div>

            <div class="form-field">
                <label for="email">Email address <span class="required-indicator" aria-hidden="true">*</span></label>
                <input 
                    type="email" 
                    id="email" 
                    name="email" 
                    required 
                    autocomplete="email"
                    aria-describedby="email-error"
                    aria-invalid="false">
                <p id="email-error" class="error-message"></p>
            </div>

            <div class="form-field">
                <label for="phone">Phone number (optional)</label>
                <input 
                    type="tel" 
                    id="phone" 
                    name="phone" 
                    autocomplete="tel"
                    aria-describedby="phone-help phone-error"
                    aria-invalid="false">
                <p id="phone-help" class="helper-text">Expected format: 123-456-7890</p>
                <p id="phone-error" class="error-message"></p>
            </div>

            <button type="submit">Send support request</button>
        </form>

        <div id="status-message" aria-live="polite"></div>
    </main>
    <script>
        document.addEventListener('DOMContentLoaded', () => {
            const form = document.getElementById('contact-form');
            const statusMessage = document.getElementById('status-message');

            const fields = {
                name: {
                    element: document.getElementById('name'),
                    errorElement: document.getElementById('name-error'),
                    validate: (value) => value.trim() !== '' ? '' : 'Error: Full name is required.'
                },
                email: {
                    element: document.getElementById('email'),
                    errorElement: document.getElementById('email-error'),
                    validate: (value) => {
                        if (!value.trim()) return 'Error: Email address is required.';
                        const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
                        return emailRegex.test(value) ? '' : 'Error: Enter a valid email address like name@example.com.';
                    }
                },
                phone: {
                    element: document.getElementById('phone'),
                    errorElement: document.getElementById('phone-error'),
                    validate: (value) => {
                        if (!value.trim()) return ''; // Optional
                        const phoneRegex = /^\d{3}-\d{3}-\d{4}$/;
                        return phoneRegex.test(value) ? '' : 'Error: Enter a valid phone number like 123-456-7890.';
                    }
                }
            };

            const validateField = (fieldId) => {
                const field = fields[fieldId];
                const error = field.validate(field.element.value);

                if (error) {
                    field.element.setAttribute('aria-invalid', 'true');
                    field.errorElement.textContent = error;
                } else {
                    field.element.setAttribute('aria-invalid', 'false');
                    field.errorElement.textContent = '';
                }
                return !error;
            };

            Object.keys(fields).forEach(fieldId => {
                fields[fieldId].element.addEventListener('blur', () => {
                    validateField(fieldId);
                });
            });

            form.addEventListener('submit', (event) => {
                event.preventDefault();

                let firstInvalidField = null;
                let isValid = true;

                Object.keys(fields).forEach(fieldId => {
                    if (!validateField(fieldId)) {
                        isValid = false;
                        if (!firstInvalidField) {
                            firstInvalidField = fields[fieldId].element;
                        }
                    }
                });

                if (!isValid) {
                    firstInvalidField.focus();
                    statusMessage.textContent = 'Please correct the errors before submitting.';
                    statusMessage.className = 'error';
                    statusMessage.setAttribute('aria-live', 'assertive');
                    return;
                }

                statusMessage.textContent = 'Thank you! Your support request has been sent.';
                statusMessage.className = 'success';
                statusMessage.setAttribute('aria-live', 'polite');
                form.reset();

                Object.keys(fields).forEach(fieldId => {
                    fields[fieldId].element.setAttribute('aria-invalid', 'false');
                });
            });
        });
    </script>
</body>
